# <uncertainty>Need to reconcile unpaid shares with any existing pending Venmo payment requests to avoid duplicates.</uncertainty>

unpaid = {
    'Adrian': {'email':'adrian_burt@gmail.com','amount':36.0},
    'Katie': {'email':'kat_simp@gmail.com','amount':30.0},
    'Melissa': {'email':'mel.bailey@gmail.com','amount':31.0},
    'Glenn': {'email':'glenn.burton@gmail.com','amount':32.0},
}

# pending_all already computed in prior step; ensure it's available. If not, fetch again.
try:
    pending_all
except NameError:
    pending_all=[]
    page_index=0
    page_limit=20
    while True:
        res=apis.venmo.show_sent_payment_requests(access_token=venmo_token,status='pending',page_index=page_index,page_limit=page_limit)
        print('pending sent page',page_index,'count',len(res))
        if not res:
            break
        pending_all.extend(res)
        if len(res)<page_limit:
            break
        page_index+=1

print('total pending sent requests in system', len(pending_all))

# filter pending by our unpaid receiver emails
pending_by_receiver = {info['email']: [] for info in unpaid.values()}
for pr in pending_all:
    recv = (pr.get('receiver') or {}).get('email')
    if recv in pending_by_receiver:
        pending_by_receiver[recv].append(pr)

for name, info in unpaid.items():
    email=info['email']; amt=info['amount']
    prs=pending_by_receiver[email]
    print('\n',name,'email',email,'pending count',len(prs))
    # show those with matching amount and description
    matches=[]
    for pr in prs:
        desc=pr.get('description','')
        a=pr.get('amount')
        try:
            af=float(a)
        except Exception:
            af=None
        if desc=='Friends Dinner' and af is not None and abs(af-amt)<1e-6:
            matches.append(pr)
    print('matches with Friends Dinner & amount',len(matches))
    if matches:
        for m in matches:
            print(' match id',m.get('payment_request_id'),'amount',m.get('amount'),'desc',m.get('description'),'created_at',m.get('created_at'))

